import { expect, test, uniqueName } from "../../fixtures";

const MiB = 1024 * 1024;

const cases = [
  {
    label: "an empty file",
    file: { name: "empty.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(0) },
    kind: "w9",
    status: 422,
    code: "empty_file",
  },
  {
    label: "a file of exactly 10 MiB + 1",
    file: {
      name: "oversized.pdf",
      mimeType: "application/pdf",
      buffer: Buffer.alloc(10 * MiB + 1, 0x25),
    },
    kind: "w9",
    status: 413,
    code: "file_too_large",
  },
  {
    label: 'a ".exe" file',
    file: {
      name: "installer.exe",
      mimeType: "application/x-msdownload",
      buffer: Buffer.from("MZ\x90\x00 not really an executable"),
    },
    kind: "w9",
    status: 415,
    code: "unsupported_type",
  },
  {
    label: "a valid text file",
    file: {
      name: "notes.txt",
      mimeType: "text/plain",
      buffer: Buffer.from("Plain text vendor notes."),
    },
    kind: "passport",
    status: 422,
    code: "validation_error",
  },
];

test.describe("DOC-04: upload vendor documents", () => {
  for (const c of cases) {
    test(
      `rejects ${c.label} as kind "${c.kind}" with ${c.status} ${c.code}`,
      { tag: "@DOC-04" },
      async ({ apiAs }) => {
        // Arrange: a vendor in draft status owned by the member's tenant
        const member = await apiAs("member");
        const created = await member.post("/api/vendors", {
          data: {
            name: uniqueName("DOC-04 Vendor"),
            category: "software",
            contact_email: `doc04-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendor.test`,
          },
        });
        expect(created.status()).toBe(201);
        const vendor = await created.json();
        expect(vendor.status).toBe("draft");

        // Act
        const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: c.kind,
            file: c.file,
          },
        });

        // Assert
        expect(response.status()).toBe(c.status);
        const body = await response.json();
        expect(body.error.code).toBe(c.code);
      },
    );
  }
});
